/bin/bash -lc "cat > /tmp/project-navigation-check/check.cjs <<'EOF'
const assert = require('node:assert/strict')
const { chromium } = require('playwright')

const projects = [
  { slug: 'acme', title: 'Acme Storefront', description: 'Commerce storefront and checkout.', activity: ['Production deployment', 'Checkout updated', 'Domain verified'] },
  { slug: 'orbit', title: 'Orbit Analytics', description: 'Product analytics and reporting.', activity: ['Report published', 'Data source added', 'Team invited'] },
]

;(async () => {
  const browser = await chromium.launch({ headless: true })
  try {
    for (const project of projects) {
      const page = await browser.newPage()
      const errors = []
      page.on('pageerror', (error) => errors.push(error.message))
      const prefetchBodies = []
      let releaseNavigation
      const navigationGate = new Promise((resolve) => { releaseNavigation = resolve })
      let navigationRequests = 0
      await page.route('**/projects/**', async (route) => {
        const headers = route.request().headers()
        if (headers.rsc && "'!headers['"'next-router-prefetch']) {
          navigationRequests++
          await navigationGate
        }
        await route.continue()
      })
      const titlePrefetched = new Promise((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error("'`No title prefetch for ${project.slug}`)), 15000)
        page.on('"'response', async (response) => {
          if ("'!response.request().headers()['"'next-router-prefetch']) return
          try {
            const body = await response.text()
            prefetchBodies.push(body)
            if (response.url().includes("'`/projects/${project.slug}`) && body.includes(project.title)) {
              clearTimeout(timeout)
              resolve()
            }
          } catch {}
        })
      })
      await page.goto('"'http://127.0.0.1:3000/')
      await titlePrefetched
      for (const body of prefetchBodies) {
        for (const candidate of projects) {
          assert("'!body.includes(candidate.description), '"'Description appeared in a prefetch')
          for (const item of candidate.activity) assert("'!body.includes(item), '"'Activity appeared in a prefetch')
        }
      }
      await page.getByRole('link', { name: project.title, exact: true }).click()
      await page.getByRole('heading', { name: project.title, exact: true }).waitFor({ state: 'visible', timeout: 5000 })
      assert(await page.getByText('Loading project details...', { exact: true }).isVisible())
      assert.equal(await page.getByText(project.description, { exact: true }).count(), 0)
      assert.equal(await page.getByRole('heading', { name: 'Recent activity' }).count(), 0)
      releaseNavigation()
      await page.getByText(project.description, { exact: true }).waitFor({ state: 'visible' })
      for (const item of project.activity) assert(await page.getByText(item, { exact: true }).isVisible())
      assert(navigationRequests > 0, 'Expected deferred navigation request')
      assert.deepEqual(errors, [])
      console.log("'`PASS ${project.slug}: prefetch contains title only; title visible with navigation paused; details and activity load after release`)
      await page.close()
    }
    const page = await browser.newPage()
    await page.goto('"'http://127.0.0.1:3000/projects/missing')
    await page.getByRole('heading', { name: 'Unknown project', exact: true }).waitFor()
    await page.getByText('This project could not be found.', { exact: true }).waitFor()
    console.log('PASS direct navigation: unknown-project fallback preserved')
  } finally {
    await browser.close()
  }
})().catch((error) => { console.error(error); process.exitCode = 1 })
